/// <summary>
/// Extension of class <c>SalesConfirmDP</c>
/// </summary>
[ExtensionOf(classStr(SalesConfirmDP))]
final class KPMGSalesConfirmDP_Extension
{    
}

Method.Source:
    /// <summary>
    /// Initializes a sales order confirmation header.
    /// </summary>
    /// <returns>
    /// The initialized <c>SalesConfirmHeaderTmp</c> sales order confirmation header record.
    /// </returns>
    protected SalesConfirmHeaderTmp initializeSalesOrderConfirmationHeader()
    {
        CompanyInfo           companyInfo           = CompanyInfo::find();
        SalesConfirmHeaderTmp salesConfirmHeaderTmp = next initializeSalesOrderConfirmationHeader();
        SalesTable            salesTable            = SalesTable::find(salesConfirmHeaderTmp.SalesId);
        METIndustryKeyTable   industryKey           = METIndustryKeyTable::find(METCustTable::find(salesTable.CustAccount).IndustryKey);
        Image                 img;
        METIndustryKeyLogo    reportLogo;
        CustConfirmTrans      KPMGCustConfirmTrans;
        
        salesConfirmHeaderTmp.CompanyEmail          = companyInfo.email();
        salesConfirmHeaderTmp.KPMGCustAccount       = salesTable.CustAccount;
        salesConfirmHeaderTmp.KPMGContactPersonId   = salesTable.contactPersonName();
        salesConfirmHeaderTmp.KPMGOrderDiscount     = salesConfirmHeaderTmp.TotalTaxBaseAmount * salesTable.DiscPercent /100;

        salesConfirmHeaderTmp.KPMGSalesOrderType    = salesTable.METSalesOrderType;
        salesConfirmHeaderTmp.KPMGCustName          = salesTable.customerName();
        salesConfirmHeaderTmp.KPMGSalesOrderDate    = DateTimeUtil::date(salesTable.CreatedDateTime);
        salesConfirmHeaderTmp.KPMGSOCreateTime      = time2Str(DateTimeUtil::time(salesTable.CreatedDateTime), TimeSeparator::Colon, TimeFormat::AMPM);
        salesConfirmHeaderTmp.KPMGSOConfirmCreateTime= time2Str(DateTimeUtil::time(this.parmCustConfirmJour().CreatedDateTime), TimeSeparator::Colon, TimeFormat::AMPM);
        salesConfirmHeaderTmp.KPMGEntityId           = strUpr(curExt());
                     
        select firstonly InventDimId from KPMGCustConfirmTrans
            where KPMGCustConfirmTrans.ConfirmId == salesConfirmHeaderTmp.ConfirmId && 
            KPMGCustConfirmTrans.SalesId == salesConfirmHeaderTmp.SalesId &&
            KPMGCustConfirmTrans.ConfirmDate == salesConfirmHeaderTmp.ConfirmDate;

        salesConfirmHeaderTmp.KPMGSiteAddress       = LogisticsLocationEntity::findPostalAddress(
            KPMGCustConfirmTrans.inventDim().inventSite(), LogisticsLocationRoleType::Delivery).Address;   

        if(industryKey)
        {
            if(industryKey.CompanyName)
            {
                salesConfirmHeaderTmp.CompanyName                       = industryKey.CompanyName;
            }
            if(industryKey.CoRegNum)
            {
                salesConfirmHeaderTmp.CompanyCoRegNum                   = industryKey.CoRegNum;
            }
            if(industryKey.SalesOrderConfirmPhone)
            {
                salesConfirmHeaderTmp.CompanyPhone                      = industryKey.SalesOrderConfirmPhone;
            }
            if(industryKey.SalesOrderConfirmFormNotes)
            {
                salesConfirmHeaderTmp.KPMGSalesOrderConfirmFormNotes    = industryKey.SalesOrderConfirmFormNotes;
            }
            reportLogo = industryKey.Logo;
            switch(reportLogo)
            {
                case METIndustryKeyLogo::Logo1:
                    img = CompanyImage::metGetImage(companyInfo);
                    break;
                case METIndustryKeyLogo::Logo2:
                    img = METCompanyImage::getImage(companyInfo, METCompanyImageType::CompanyLogo);
                    break;
                case METIndustryKeyLogo::Logo3:
                    img = METCompanyImage::getImage(companyInfo, METCompanyImageType::CompanyLogo3);
                    break;
                case METIndustryKeyLogo::Logo4:
                    img = METCompanyImage::getImage(companyInfo, METCompanyImageType::CompanyLogo4);
                    break;
                default:
                    img = CompanyImage::metGetImage(companyInfo);
                    break;
            }
            if(img)
            {
                salesConfirmHeaderTmp.CompanyLogo = img.getData();
            }
        }

        return salesConfirmHeaderTmp;
    }

    /// <summary>
    /// Initializes a sales order confirmation line.
    /// </summary>
    /// <param name = "_salesConfirmHeaderTmp">
    /// A <c>SalesConfirmHeaderTmp</c> record which is the sales order confirmation header.
    /// </param>
    /// <param name = "_confirmationLineSelection">
    /// A <c>SalesConfirmDPConfirmationLineQuerySelection</c> object which the sales order confirmation line should be initialized from.
    /// </param>
    /// <returns>
    /// The initialized <c>SalesConfirmDetailsTmp</c> sales order confirmation line record.
    /// </returns>
    protected SalesConfirmDetailsTmp initializeSalesOrderConfirmationLine(
        SalesConfirmHeaderTmp                           _salesConfirmHeaderTmp,
        SalesConfirmDPConfirmationLineQuerySelection    _confirmationLineSelection)
    {
        SalesConfirmDetailsTmp  salesConfirmTmp;
        CustConfirmTrans        kpmgCustConfirmTrans    = _confirmationLineSelection.parmCustConfirmTrans();
        SalesLine               SalesLine               = kpmgCustConfirmTrans.salesLine();
        METSalesLine            METSalesLine            = METSalesLine::find(SalesLine.RecId);
        SalesQty                qtyReservedRem, reserveQty;//, pickedQty;

        salesConfirmTmp = next initializeSalesOrderConfirmationLine(_salesConfirmHeaderTmp, _confirmationLineSelection);
        
        if (!salesConfirmTmp.TaxAmount)
        {
            salesConfirmTmp.TaxAmount           = kpmgCustConfirmTrans.TaxAmount;
        }
        salesConfirmTmp.KPMGLineNo              = real2int(kpmgCustConfirmTrans.LineNum);
        salesConfirmTmp.KPMGTotalPriceIncGST    = kpmgCustConfirmTrans.LineAmount + salesConfirmTmp.TaxAmount;
        salesConfirmTmp.KPMGBarCode             = SalesLine.BarCode;
        salesConfirmTmp.KPMGIndicators          = METSalesLine.Indicators;
        salesConfirmTmp.KPMGReasonId            = METSalesLine.ReasonId;
        salesConfirmTmp.KPMGSubstituteOriginalItemID = METSalesLine.SubstituteOriginalItemID;
        salesConfirmTmp.KPMGCustAvailDate       = MetItemSiteSettingsSetup::find(SalesLine.itemId, SalesLine.inventDim().InventSiteId).CustAvailDate;
        reserveQty                              = abs(SalesLine.reservedPhysical()) + abs(SalesLine.pickedInTotalInventUnit());
        if(reserveQty) 
        {
            qtyReservedRem                          = abs(SalesLine.unitConvertSales2Invent(1));
            if(qtyReservedRem)
            {
                if(reserveQty mod qtyReservedRem == 0)
                {
                    salesConfirmTmp.KPMGSupplyQty           = reserveQty/qtyReservedRem;
                }
                else
                {
                    salesConfirmTmp.KPMGSupplyQty           = str2Num('0.'+ int2Str(reserveQty));
                }
            }
            else
            {
                salesConfirmTmp.KPMGSupplyQty           = reserveQty;
            }
        }
        if(SalesLine.PdsCWQty)
        {
            salesConfirmTmp.KPMGTotalCartonsSupplied    = abs(SalesLine.pdsCWPickedInTotal()) + abs(SalesLine.pdsCWReservedPhysical());
            salesConfirmTmp.KPMGTotalCartonsAdded       = abs(SalesLine.PdsCWQty);
        }
        else
        {
            salesConfirmTmp.KPMGTotalCartonsSupplied    = abs(SalesLine.pickedInTotalSalesUnit()) + abs(SalesLine.reservedPhysicalInSalesUnit());
            salesConfirmTmp.KPMGTotalCartonsAdded       = salesConfirmTmp.Qty;
        }        

        if(strFind(metsalesLine.Indicators, METConstants::PromotionInd, 1, strLen(metsalesLine.Indicators)))
        {
            salesConfirmTmp.KPMGIsPromotionInd  = NoYes::Yes;
        }
        salesConfirmTmp.KPMGRebateFees          = MarkupTrans::findValue(tableNum(CustConfirmTrans), kpmgCustConfirmTrans.RecId).CalculatedAmount;        
        
        return salesConfirmTmp; 
    }
